// routes / users.js

var User = require('../models/user');
var Task = require('../models/task');
var response = require('../utils/response');
var isValidId = require('../utils/ids').isValidId;
var findMany = require('../utils/query').findMany;
var handleError = response.handleError;
var parseSelect = require('../utils/query').parseSelect;
var validateUserBody = require('../utils/validate').validateUserBody;
var references = require('../utils/references');

var send = response.send;
var serverError = response.serverError;

module.exports = function (router) {

    // ----- /api/users -----
    var usersRoute = router.route('/users');

    // GET /api/users: list users (supports query parameters)
    usersRoute.get(async function (req, res) {
        try {
            var users = await findMany(User, req.query);
            return send(res, 200, 'OK', users);
        } catch (err) {
            return handleError(res, err);
        }
    });

    // ----- /api/users/:id -----
    var userRoute = router.route('/users/:id');

    // GET /api/users/:id: one user, or 404 (supports select)
    userRoute.get(async function (req, res) {
        try {
            if (!isValidId(req.params.id)) {
                return send(res, 404, 'User not found', {});
            }
            var select = parseSelect(req.query);

            var dbQuery = User.findById(req.params.id);
            if (select !== undefined) {
                dbQuery = dbQuery.select(select);
            }
            var user = await dbQuery.exec();

            if (!user) {
                return send(res, 404, 'User not found', {});
            }
            return send(res, 200, 'OK', user);
        } catch (err) {
            return handleError(res, err);
        }
    });

    // PUT /api/users/:id: replace a user (and update their tasks to match)
    userRoute.put(async function (req, res) {
        try {
            // 1. URL id must point to an existing user
            if (!isValidId(req.params.id)) {
                return send(res, 404, 'User not found', {});
            }
            var user = await User.findById(req.params.id);
            if (!user) {
                return send(res, 404, 'User not found', {});
            }

            // 2. Body format and duplicate email (400)
            var fields = validateUserBody(req.body);
            var emailOwner = await User.findOne({ email: fields.email, _id: { $ne: user._id } });
            if (emailOwner) {
                return send(res, 400, 'A user with this email already exists.', {});
            }

            // 3-4. Referenced tasks exist (404) and are not completed (400)
            await references.checkPendingTasks(fields.pendingTasks);

            // Remember the old list before overwriting it
            var oldPendingTasks = user.pendingTasks.map(String);

            user.name = fields.name;
            user.email = fields.email;
            user.pendingTasks = fields.pendingTasks;
            var saved = await user.save();

            await references.syncUserToTasks(saved, oldPendingTasks);
            return send(res, 200, 'User updated', saved);
        } catch (err) {
            return handleError(res, err);
        }
    });

    // DELETE /api/users/:id: delete a user and unassign all their tasks
    userRoute.delete(async function (req, res) {
        try {
            if (!isValidId(req.params.id)) {
                return send(res, 404, 'User not found', {});
            }
            var user = await User.findById(req.params.id);
            if (!user) {
                return send(res, 404, 'User not found', {});
            }

            // Keep the two-way reference: no task may still point to this user
            await Task.updateMany(
                { assignedUser: String(user._id) },
                { $set: { assignedUser: '', assignedUserName: 'unassigned' } }
            );

            await user.deleteOne();
            return send(res, 204, 'User deleted', {});
        } catch (err) {
            return handleError(res, err);
        }
    });

    // POST /api/users: create a user (and assign the tasks in pendingTasks to them)
    usersRoute.post(async function (req, res) {
        try {
            var fields = validateUserBody(req.body); // 400: format

            var existing = await User.findOne({ email: fields.email });
            if (existing) {
                return send(res, 400, 'A user with this email already exists.', {});
            }

            await references.checkPendingTasks(fields.pendingTasks); // 404 / 400

            var saved = await new User(fields).save();
            await references.syncUserToTasks(saved, []); // new user: no previous tasks
            return send(res, 201, 'User created', saved);
        } catch (err) {
            return handleError(res, err);
        }
    });

    return router;
};

// utils / query.js

// Builds and runs the database query for GET /users and GET /tasks
// from the query string parameters (where, sort, select, ...).

// Create an error that should be sent to the client as a 400.
function badRequest(message) {
    var err = new Error(message);
    err.status = 400;
    return err;
}

// Create an error that should be sent to the client as a 404.
function notFound(message) {
    var err = new Error(message);
    err.status = 404;
    return err;
}

// Read one query string parameter and parse it as JSON.
// Returns undefined if the parameter is not in the URL.
function parseJsonParam(query, name) {
    var raw = query[name];
    if (raw === undefined) {
        return undefined;
    }

    try {
        return JSON.parse(raw);
    } catch (e) {
        throw badRequest('The "' + name + '" parameter must be valid JSON.');
    }
}

// True for {...} objects, false for arrays, null, numbers, strings.
function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Read and check the "select" parameter.
// Used by the list routes and by /users/:id and /tasks/:id.
function parseSelect(query) {
    var select = parseJsonParam(query, 'select');
    if (select === undefined) {
        return undefined;
    }

    if (!isPlainObject(select)) {
        throw badRequest('The "select" parameter must be a JSON object.');
    }

    var hasInclude = false;
    var hasExclude = false;
    Object.keys(select).forEach(function (field) {
        var value = select[field];
        if (value !== 1 && value !== 0) {
            throw badRequest('Each field in "select" must be 1 (include) or 0 (exclude).');
        }

        if (field === '_id') {
            return; // _id is the one field allowed to differ, skip it
        }

        if (value === 1) {
            hasInclude = true;
        } else {
            hasExclude = true;
        }
    });

    if (hasInclude && hasExclude) {
        throw badRequest('"select" cannot mix included (1) and excluded (0) fields, except for "_id".');
    }
    return select;
}

// Read a parameter that must be a whole number >= 0 (used for skip and limit).
function parseNonNegativeInt(query, name) {
    var value = parseJsonParam(query, name);
    if (value === undefined) {
        return undefined;
    }

    if (!Number.isInteger(value) || value < 0) {
        throw badRequest('The "' + name + '" parameter must be a whole number of 0 or more.');
    }

    return value;
}

// Run a find() on the given model using the URL's query parameters.
// Returns a list of documents, or a number if count=true.
async function findMany(Model, query, defaultLimit) {
    // ----- where -----
    var where = parseJsonParam(query, 'where');
    if (where !== undefined && !isPlainObject(where)) {
        throw badRequest('The "where" parameter must be a JSON object.');
    }

    // ----- sort -----
    var sort = parseJsonParam(query, 'sort');
    if (sort !== undefined) {
        if (!isPlainObject(sort)) {
            throw badRequest('The "sort" parameter must be a JSON object.');
        }

        Object.keys(sort).forEach(function (field) {
            if (sort[field] !== 1 && sort[field] !== -1) {
                throw badRequest('Each field in "sort" must be 1 (ascending) or -1 (descending).');
            }
        });
    }

    // ----- select -----
    var select = parseSelect(query);

    // ----- skip and limit -----
    var skip = parseNonNegativeInt(query, 'skip');
    var explicitLimit = parseNonNegativeInt(query, 'limit'); // what the client sent, if anything
    var limit = explicitLimit === undefined ? defaultLimit : explicitLimit;

    // ----- count -----
    var count = parseJsonParam(query, 'count');
    if (count !== undefined && typeof count !== 'boolean') {
        throw badRequest('The "count" parameter must be true or false.');
    }

    // ----- count=true: return a number instead of documents -----
    if (count === true) {
        var countQuery = Model.countDocuments(where || {});
        if (skip !== undefined) {
            countQuery = countQuery.skip(skip);
        }

        if (explicitLimit !== undefined && explicitLimit > 0) {
            countQuery = countQuery.limit(explicitLimit);
        }

        return countQuery.exec();
    }

    // ----- otherwise: build the find query step by step, then run it -----
    var dbQuery = Model.find(where || {});
    if (sort !== undefined) {
        dbQuery = dbQuery.sort(sort);
    }
    if (select !== undefined) {
        dbQuery = dbQuery.select(select);
    }
    if (skip !== undefined) {
        dbQuery = dbQuery.skip(skip);
    }
    if (limit !== undefined) {
        dbQuery = dbQuery.limit(limit);
    }

    return dbQuery.exec();
}

module.exports = { findMany: findMany, badRequest: badRequest, notFound: notFound, parseSelect: parseSelect };

// utils / validate.js

// Validation for request bodies of POST and PUT on users and tasks.
var badRequest = require('./query').badRequest;

var isValidId = require('./ids').isValidId;

// True for a string with at least one non-space character.
function isNonEmptyString(value) {
    return typeof value === 'string' && value.trim() !== '';
}

// Accepts true/false, or "true"/"false" (form data sends strings).
function parseBoolean(value, name) {
    if (value === true || value === 'true') {
        return true;
    }
    if (value === false || value === 'false') {
        return false;
    }
    throw badRequest('"' + name + '" must be true or false.');
}

// Accepts a date string ("2026-11-01") or a timestamp in milliseconds,
// either as a number or as a string of digits (form data).
function parseDate(value, name) {
    if (typeof value === 'string' && /^-?\d+$/.test(value.trim())) {
        value = Number(value);
    }
    if (typeof value !== 'string' && typeof value !== 'number') {
        throw badRequest('"' + name + '" must be a valid date.');
    }
    var date = new Date(value);
    if (isNaN(date.getTime())) {
        throw badRequest('"' + name + '" must be a valid date.');
    }
    return date;
}

// Check a user body and return only the fields we allow.
function validateUserBody(body) {
    body = body || {};
    if (!isNonEmptyString(body.name)) {
        throw badRequest('A user must have a name.');
    }
    if (!isNonEmptyString(body.email)) {
        throw badRequest('A user must have an email.');
    }

    // pendingTasks: a list of task ids (missing means an empty list)
    var pendingTasks = [];
    if (body.pendingTasks !== undefined && body.pendingTasks !== null) {
        var list = body.pendingTasks;
        // Form data sends a single value as a plain string
        if (typeof list === 'string') {
            list = list === '' ? [] : [list];
        }
        if (!Array.isArray(list)) {
            throw badRequest('"pendingTasks" must be a list of task ids.');
        }
        list.forEach(function (id) {
            if (typeof id !== 'string' || !isValidId(id)) {
                throw badRequest('"pendingTasks" contains an invalid task id.');
            }
        });
        // Remove duplicates: the same task listed twice is still one task
        pendingTasks = Array.from(new Set(list));
    }

    return { name: body.name, email: body.email, pendingTasks: pendingTasks };
}

// Check a task body and return only the fields we allow, with defaults filled in.
function validateTaskBody(body) {
    body = body || {};
    if (!isNonEmptyString(body.name)) {
        throw badRequest('A task must have a name.');
    }
    if (body.deadline === undefined || body.deadline === null || body.deadline === '') {
        throw badRequest('A task must have a deadline.');
    }
    var deadline = parseDate(body.deadline, 'deadline');

    var description = '';
    if (body.description !== undefined && body.description !== null) {
        if (typeof body.description !== 'string') {
            throw badRequest('"description" must be text.');
        }
        description = body.description;
    }

    var completed = false;
    if (body.completed !== undefined && body.completed !== null) {
        completed = parseBoolean(body.completed, 'completed');
    }

    // assignedUser: "" means unassigned, otherwise it must be a valid id
    var assignedUser = '';
    if (body.assignedUser !== undefined && body.assignedUser !== null) {
        if (typeof body.assignedUser !== 'string') {
            throw badRequest('"assignedUser" must be a user id, or "" for no user.');
        }
        assignedUser = body.assignedUser;
        if (assignedUser !== '' && !isValidId(assignedUser)) {
            throw badRequest('"assignedUser" is not a valid user id.');
        }
    }

    // assignedUserName: optional (undefined = not given, we fill it in later)
    var assignedUserName;
    if (body.assignedUserName !== undefined && body.assignedUserName !== null) {
        if (typeof body.assignedUserName !== 'string') {
            throw badRequest('"assignedUserName" must be text.');
        }
        assignedUserName = body.assignedUserName;
    }

    // An unassigned task can't claim to belong to someone
    if (assignedUser === '' && assignedUserName !== undefined &&
        assignedUserName !== 'unassigned' && assignedUserName !== '') {
        throw badRequest('An unassigned task must have "assignedUserName" set to "unassigned".');
    }

    return {
        name: body.name,
        description: description,
        deadline: deadline,
        completed: completed,
        assignedUser: assignedUser,
        assignedUserName: assignedUserName
    };
}

module.exports = { validateUserBody: validateUserBody, validateTaskBody: validateTaskBody };

